    @Override public boolean onTouchEvent(MotionEvent e){scaler.onTouchEvent(e);if(e.getActionMasked()==MotionEvent.ACTION_DOWN){lastX=downX=e.getX();lastY=downY=e.getY();dragName=draw.pick(e.getX(),e.getY(),getWidth(),getHeight());draw.selectedName=dragName;dragged=false;return true;}if(e.getActionMasked()==MotionEvent.ACTION_UP){if(dragName!=null&&dragListener!=null&&dragged)dragListener.onDrag(dragName,0,0,true);if(!dragged&&Math.abs(e.getX()-downX)<12&&Math.abs(e.getY()-downY)<12&&tapListener!=null&&dragName!=null)tapListener.onTap(dragName);dragName=null;return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE){if(e.getPointerCount()==1&&!scaler.isInProgress()){float dx=e.getX()-lastX,dy=e.getY()-lastY;if(dragName!=null&&(Math.abs(e.getX()-downX)+Math.abs(e.getY()-downY)>8)){dragged=true;draw.moveObject(dragName,dx*.02f,-dy*.02f);if(dragListener!=null)dragListener.onDrag(dragName,dx*.02f,-dy*.02f,false);}else if(dragName==null){draw.yaw-=dx*.35f;draw.pitch=Math.max(-75,Math.min(75,draw.pitch+dy*.3f));}requestRender();}lastX=e.getX();lastY=e.getY();return true;}return true;}
